package java.util;
public class EnumMap<K extends Enum<K>,V> extends AbstractMap<K,V> implements java.io.Serializable,Cloneable {private final Class<K> type;private final K[] universe;private final Object[] values;private final boolean[] present;private int count;public EnumMap(Class<K> type){this.type=type;universe=type.getEnumConstants();if(universe==null)throw new ClassCastException();values=new Object[universe.length];present=new boolean[universe.length];}public EnumMap(EnumMap<K,? extends V> m){this(m.type);putAll(m);}public EnumMap(Map<K,? extends V> m){this(typeOf(m));putAll(m);}private static <K extends Enum<K>> Class<K> typeOf(Map<K,?> m){if(m instanceof EnumMap)return ((EnumMap<K,?>)m).type;if(m.isEmpty())throw new IllegalArgumentException("Specified map is empty");return m.keySet().iterator().next().getDeclaringClass();}private int index(Object k){if(!(k instanceof Enum))return -1;Enum e=(Enum)k;return e.getDeclaringClass()==type?e.ordinal():-1;}public int size(){return count;}public boolean containsKey(Object k){int i=index(k);return i>=0&&present[i];}public V get(Object k){int i=index(k);return i<0||!present[i]?null:(V)values[i];}public V put(K k,V v){if(k==null)throw new NullPointerException();int i=index(k);if(i<0)throw new ClassCastException();V old=(V)values[i];if(!present[i]){present[i]=true;count++;}values[i]=v;return old;}public V remove(Object k){int i=index(k);if(i<0||!present[i])return null;V old=(V)values[i];present[i]=false;values[i]=null;count--;return old;}public void clear(){for(int i=0;i<values.length;i++){values[i]=null;present[i]=false;}count=0;}public Set<Entry<K,V>> entrySet(){return new AbstractSet<Entry<K,V>>(){public int size(){return count;}public Iterator<Entry<K,V>> iterator(){return new Iterator<Entry<K,V>>(){int i,last=-1;public boolean hasNext(){while(i<present.length&&!present[i])i++;return i<present.length;}public Entry<K,V> next(){if(!hasNext())throw new NoSuchElementException();final K k=universe[i];last=i++;return new Entry<K,V>(){public K getKey(){return k;}public V getValue(){return EnumMap.this.get(k);}public V setValue(V v){return EnumMap.this.put(k,v);}public boolean equals(Object o){return new SimpleEntry<K,V>(k,getValue()).equals(o);}public int hashCode(){return new SimpleEntry<K,V>(k,getValue()).hashCode();}public String toString(){return k+"="+getValue();}};}public void remove(){if(last<0)throw new IllegalStateException();EnumMap.this.remove(universe[last]);last=-1;}};}};}public EnumMap<K,V> clone(){return new EnumMap<K,V>(this);}}
